def identify_bands(pattern_row_info):
    """Group consecutive non-background rows into bands"""
    bands = []
    current_band = []
    for r, rightmax, cols in pattern_row_info:
        if rightmax >= 0:
            if current_band and current_band[-1][0] + 1 == r:
                current_band.append((r, rightmax, cols))
            else:
                if current_band:
                    bands.append(current_band)
                current_band = [(r, rightmax, cols)]
        else:
            if current_band:
                bands.append(current_band)
                current_band = []
