        print(f"  fill cols: {fill_cols}")

# Count number of gaps (non-consecutive transitions) from left
def count_gaps_left(pattern_cols):
    """Count transitions that are not consecutive"""
    if len(pattern_cols) <= 1:
        return 0
    gaps = 0
    for c in range(1, len(pattern_cols)):
        if pattern_cols[c] != pattern_cols[c-1] + 1:
            gaps += 1
    return gaps

