# Count number of consecutive runs
def count_runs(pattern_cols):
    if not pattern_cols:
        return []
    runs = []
    current_run = [pattern_cols[0]]
    for c in pattern_cols[1:]:
        if c == current_run[-1] + 1:
            current_run.append(c)
        else:
            runs.append(current_run)
            current_run = [c]
    runs.append(current_run)
    return runs

